  busy=true;print.Enabled=false;if(!send)preview.ClearPages();info.Text=Loc.T(send?"Odosielam do tlačiarne…":discover?"Načítavam tlačiarne…":"Pripravujem náhľad…");if(send){sending=true;printers.Enabled=papers.Enabled=landscape.Enabled=copies.Enabled=mediaProfiles.Enabled=ignoreDriverMargins.Enabled=offsetX.Enabled=offsetY.Enabled=false;}
