   using(var doc=new LabelPrintDocument(renderLabel,renderPlan)){if(printer==null){printer=new PrinterSettings();if(!string.IsNullOrEmpty(name))printer.PrinterName=name;settings=(PageSettings)printer.DefaultPageSettings.Clone();settings.Margins=new Margins(0,0,0,0);correctionX=correctionY=0;ignoreMargins=false;if(profile!=null){result.Profile=profile;correctionX=profile.X;correctionY=profile.Y;ignoreMargins=profile.IgnoreDriverMargins;settings.Landscape=profile.Landscape;bool found=false;foreach(PaperSize size in printer.PaperSizes)if(size.PaperName==profile.Paper&&size.Width==profile.Width&&size.Height==profile.Height){settings.PaperSize=size;found=true;break;}if(!found){settings.PaperSize=new PaperSize(profile.Paper??profile.DisplayName,profile.Width,profile.Height);result.ProfileWarning=Loc.T("Profil používa vlastné rozmery média. Overte ich v nastavení ovládača.");}}}doc.OffsetX=correctionX;doc.OffsetY=correctionY;doc.IgnoreDriverMargins=ignoreMargins;result.IgnoreDriverMargins=ignoreMargins;result.OffsetX=correctionX;result.OffsetY=correctionY;printer.Copies=count;doc.PrinterSettings=printer;doc.DefaultPageSettings=settings;var readyPage=(PageSettings)settings.Clone();readyPage.PaperSize=settings.PaperSize;readyPage.Landscape=settings.Landscape;result.Printer=(PrinterSettings)printer.Clone();result.Settings=readyPage;if(cachedPapers!=null)result.Papers=cachedPapers;else{var sizes=new List<PaperSize>();if(printer.IsValid)foreach(PaperSize size in printer.PaperSizes)sizes.Add(size);result.Papers=sizes.ToArray();}if(!Array.Exists(result.Papers,size=>size.Width==settings.PaperSize.Width&&size.Height==settings.PaperSize.Height))result.ProfileWarning=Loc.T("Profil používa vlastné rozmery média. Overte ich v nastavení ovládača.");result.Count=doc.PageCount;
    doc.ValidatePrinter();result.Report=doc.InspectOutput();if(result.ProfileWarning!=null)result.Report.AddWarning(result.ProfileWarning);result.Warnings=result.Report.Messages().ToArray();if(send&&(result.Report.Blocking||result.Report.Fingerprint!=accepted)){result.RequiresReview=true;}else if(send){doc.PrintController=new StandardPrintController();doc.Print();result.Cancelled=doc.Cancelled;result.Sent=!doc.Cancelled;}else{result.Paper=new SizeF(Math.Max((float)doc.WidthMm,settings.Bounds.Width*.254f),Math.Max((float)doc.HeightMm,settings.Bounds.Height*.254f));result.Image=doc.CreatePreview(Math.Max(0,Math.Min(doc.PageCount-1,index)),result.Paper);var a=settings.PrintableArea;result.Printable=new RectangleF(a.X*.254f,a.Y*.254f,a.Width*.254f,a.Height*.254f);}}
