 void Deliver(int ticket,PrintResult result){lock(deliveryGate){if(closed||ticket!=version){result.Dispose();return;}if(delivery!=null)delivery.Dispose();delivery=result;}try{BeginInvoke((Action)delegate{PrintResult ready;lock(deliveryGate){if(delivery!=result)return;ready=delivery;delivery=null;}if(ready==null)return;using(ready){if(closed||ticket!=version)return;ApplyResult(ready);}});}catch(InvalidOperationException){lock(deliveryGate){if(delivery==result){delivery=null;result.Dispose();}}}}
 void ApplyResult(PrintResult result){updating=true;try{offsetX.Value=Math.Max(-100,Math.Min(100,(decimal)result.OffsetX));offsetY.Value=Math.Max(-100,Math.Min(100,(decimal)result.OffsetY));if(result.Printers!=null){printers.Items.Clear();printers.Items.AddRange(result.Printers);}if(result.Printer!=null&&result.Papers!=null){selectedPrinter=result.Printer;selectedPage=result.Settings;knownPapers=result.Papers;printerName.Text=selectedPrinter.PrinterName;printerTip.SetToolTip(printers,printerName.Text);printerTip.SetToolTip(printerName,printerName.Text);if(!printers.Items.Contains(printerName.Text))printers.Items.Add(printerName.Text);printers.SelectedItem=printerName.Text;papers.Items.Clear();PaperSize chosen=null;foreach(var size in result.Papers){papers.Items.Add(size);if(size.RawKind==selectedPage.PaperSize.RawKind&&size.Width==selectedPage.PaperSize.Width&&size.Height==selectedPage.PaperSize.Height)chosen=size;}if(chosen==null){chosen=selectedPage.PaperSize;papers.Items.Add(chosen);}papers.SelectedItem=chosen;landscape.Checked=selectedPage.Landscape;}
   ignoreDriverMargins.Checked=result.IgnoreDriverMargins;if(result.Profile!=null){profileName.Text=result.Profile.DisplayName;RefreshProfiles(result.Profile.Printer,result.Profile.DisplayName);}page.Maximum=Math.Max(1,result.Count);pageTools.Visible=result.Count>1;pageTotal.Text="/ "+result.Count;warnings=result.Warnings??new string[0];currentReport=result.Report;review.Enabled=currentReport!=null;UpdateOutputSummary();
   if(result.Error!=null){info.Text=Loc.T(sending?"Tlač sa nepodarila: ":"Náhľad nie je dostupný: ")+result.Error;print.Enabled=false;}
   else if(result.RequiresReview){info.Text=Loc.T("Nastavenia alebo upozornenia sa zmenili. Skontrolujte výstup znova.");print.Enabled=currentReport!=null&&!currentReport.Blocking;}
   else if(result.Cancelled){info.Text=Loc.T("Tlač bola zrušená.");print.Enabled=true;}else if(result.Sent){info.Text=Loc.T("Úloha bola odoslaná do tlačového systému Windows.");print.Enabled=true;}
   else{preview.SetPage(result.Image,result.Paper,result.Printable);result.Image=null;preview.Page=(int)page.Value-1;double documentWidth=outputPlan==null?(snapshot.UsePaper||snapshot.Sheet?snapshot.PageWidth:snapshot.Width):outputPlan.Width,documentHeight=outputPlan==null?(snapshot.UsePaper||snapshot.Sheet?snapshot.PageHeight:snapshot.Height):outputPlan.Height;paperInfo.Text=Loc.T("Dokument")+": "+documentWidth.ToString("0.##")+" × "+documentHeight.ToString("0.##")+" mm\r\n"+Loc.T("Papier podľa ovládača")+": "+(selectedPage.Bounds.Width*.254).ToString("0.##")+" × "+(selectedPage.Bounds.Height*.254).ToString("0.##")+" mm\r\n"+Loc.T("Mierka tlače: 100 %");info.Text=warnings.Length==0?Loc.T("Pripravené"):Loc.T(currentReport!=null&&currentReport.Blocking?"Výstup blokujú chyby":"Skontrolujte upozornenia")+" ("+warnings.Length+")";info.AccessibleDescription=string.Join("\r\n",warnings);printerTip.SetToolTip(info,info.AccessibleDescription);print.Enabled=currentReport!=null&&!currentReport.Blocking;PreviewBuilds++;}
  }finally{updating=false;sending=false;busy=false;printers.Enabled=papers.Enabled=landscape.Enabled=copies.Enabled=mediaProfiles.Enabled=ignoreDriverMargins.Enabled=offsetX.Enabled=offsetY.Enabled=true;}if(PreviewReady!=null)PreviewReady(this,EventArgs.Empty);
 }
 public bool ConfigurePrinter(Func<PrintDialog,DialogResult> show){if(selectedPrinter==null||sending||busy)return false;try{using(var dialog=new PrintDialog{PrinterSettings=(PrinterSettings)selectedPrinter.Clone(),UseEXDialog=true,AllowSomePages=false,AllowSelection=false,AllowCurrentPage=false,AllowPrintToFile=false}){dialog.PrinterSettings.DefaultPageSettings.PaperSize=selectedPage.PaperSize;dialog.PrinterSettings.DefaultPageSettings.Landscape=selectedPage.Landscape;dialog.PrinterSettings.Copies=(short)copies.Value;if(show(dialog)!=DialogResult.OK)return false;selectedPrinter=(PrinterSettings)dialog.PrinterSettings.Clone();selectedPage=(PageSettings)dialog.PrinterSettings.DefaultPageSettings.Clone();knownPapers=null;copies.Value=Math.Max(1,(int)selectedPrinter.Copies);StartRequest(false,false);return true;}}catch(Exception ex){info.Text=ex.Message;return false;}}
 void UpdateOutputSummary(){jobSummary.Text=new OutputSummary(outputPlan,(int)copies.Value).ToString();}
 void Review(bool submit){if(currentReport==null||sending||busy)return;var report=currentReport;using(var dialog=new OutputReviewDialog(report,(int)copies.Value,Loc.T("Tlačiť"),printerName.Text,Font,FindForm()==null?null:FindForm().Icon)){if(calibrationStyle!=null)calibrationStyle(dialog);if(dialog.ShowDialog(this)!=DialogResult.OK){if(dialog.EditIssue!=null&&EditIssueRequested!=null){if(BackRequested!=null)BackRequested(this,EventArgs.Empty);EditIssueRequested(dialog.EditIssue);}return;}if(submit&&Ready&&ReferenceEquals(report,currentReport)){approvedFingerprint=report.Fingerprint;StartRequest(false,true);}}}
 void Submit(){if(!Ready||sending)return;Review(true);}
 void Back(){if(sending){info.Text=Loc.T("Odosielanie už prebieha. Úlohu môžete zrušiť vo fronte Windows.");}if(BackRequested!=null)BackRequested(this,EventArgs.Empty);}
 protected override bool ProcessCmdKey(ref Message msg,Keys key){if(key==Keys.Escape){Back();return true;}return base.ProcessCmdKey(ref msg,key);}
 protected override void Dispose(bool disposing){if(disposing){lock(deliveryGate){closed=true;version++;if(delivery!=null){delivery.Dispose();delivery=null;}}PrintWorker.Cancel(this);debounce.Dispose();printerTip.Dispose();preview.ClearPages();}base.Dispose(disposing);}
}
